    is_space c ⦃ b => b = false → Good c ⦄ := by
  unfold is_space
  split_ifs
  all_goals first
    | (apply WP.spec_ok.mpr; intro h; simp at h; done)
    | (apply WP.spec_ok.mpr; intro _; simp [Good] <;> agrind)
    | (apply WP.spec_ok.mpr; intro _; simp [Good] <;> scalar_tac)
    | (apply WP.spec_ok.mpr; intro _; simp_all [Good]; done)
