/// `char::is_whitespace`: the Unicode White_Space property, spelled out.
pub fn is_space(c: u32) -> bool {
    if c < 0x09 {
        false
    } else if c <= 0x0D {
        true
    } else if c == 0x20 {
        true
    } else if c == 0x85 {
        true
    } else if c == 0xA0 {
        true
    } else if c == 0x1680 {
        true
    } else if c < 0x2000 {
        false
    } else if c <= 0x200A {
        true
    } else if c == 0x2028 {
        true
    } else if c == 0x2029 {
        true
    } else if c == 0x202F {
        true
    } else if c == 0x205F {
        true
    } else if c == 0x3000 {
        true
    } else {
        false
    }
}

/// Words joined by single spaces, then the first `limit` code points.
pub fn one_line(text: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut pending_space = false;
    let mut i = 0;
    while i < text.len() {
        let c = text[i];
        if is_space(c) {
            if out.len() > 0 {
                pending_space = true;
            }
        } else {
            if pending_space {
                if out.len() < limit {
                    out.push(0x20);
                }
                pending_space = false;
            }
            if out.len() < limit {
                out.push(c);
            }
        }
        i += 1;
    }
    out
}

pub fn truncate(xs: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut i = 0;
    while i < xs.len() && i < limit {
        out.push(xs[i]);
        i += 1;
    }
    out
}
