    } else if c < 0x205F {
        false
    } else if c < 0x2060 {
        true
    } else if c < 0x3000 {
        false
    } else if c < 0x3001 {
        true
    } else {
        false
    }
}

/// Words joined by single spaces, then the first `limit` code points.
pub fn one_line(text: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut pending_space = false;
    let mut i = 0;
    while i < text.len() {
        let c = text[i];
        if is_space(c) {
            if out.len() > 0 {
                pending_space = true;
            }
        } else {
            if pending_space {
                out.push(0x20);
                pending_space = false;
            }
            out.push(c);
        }
        i += 1;
    }
    truncate(&out, limit)
}

pub fn truncate(xs: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut i = 0;
    while i < xs.len() && i < limit {
        out.push(xs[i]);
        i += 1;
    }
    out
}
