theorem spec_of_eq {α : Type} {x : Result α} {y : α} {P : α → Prop} (h : x = ok y) (hP : P y) :
    x ⦃ r => P r ⦄ := by
  subst h
  first
  | exact hP
  | (simp only [WP.spec_ok]; exact hP)
  | (simpa using hP)
  | (simp [WP.spec, hP])

theorem ok_bind' {α β : Type} (a : α) (f : α → Result β) : (ok a >>= f) = f a := by
  first
  | rfl
  | simp [Bind.bind]

theorem bind_assoc' {α β γ : Type} (x : Result α) (f : α → Result β) (g : β → Result γ) :
    (x >>= f >>= g) = (x >>= fun a => f a >>= g) := by
  cases x <;> rfl

theorem ite_bind' {α β : Type} (c : Prop) [Decidable c] (a b : Result α) (f : α → Result β) :
    ((if c then a else b) >>= f) = (if c then a >>= f else b >>= f) := by
  by_cases h : c
  · first
    | rw [if_pos h, if_pos h]
    | simp [h]
  · first
    | rw [if_neg h, if_neg h]
    | simp [h]

theorem is_space_ex (c : U32) : ∃ b, is_space c = ok b ∧ (b = false → c.val ∉ L) := by
  unfold is_space
  split_ifs <;> refine ⟨_, rfl, fun hb h => ?_⟩ <;>
    (first
      | exact absurd hb (by decide)
      | ((first
          | simp only [L, List.mem_cons, List.mem_singleton, List.not_mem_nil, or_false] at h
          | simp [L] at h) <;>
         (first
          | scalar_tac
          | (rcases h with h | h | h | h | h | h | h <;> scalar_tac))))

@[step] theorem is_space_spec (c : U32) : is_space c ⦃ b => b = false → c.val ∉ L ⦄ := by
  obtain ⟨b, hb, hP⟩ := is_space_ex c
  exact spec_of_eq hb hP

syntax "elem_tac" : tactic
syntax "good_tac" : tactic
syntax "fin_tac" : tactic

macro_rules
  | `(tactic| elem_tac) => `(tactic| first
