      | (refine good_push ?_ ?_ (by assumption) <;> first | good_tac | elem_tac))

macro_rules
  | `(tactic| fin_tac) => `(tactic| first
      | done
      | rfl
      | good_tac
      | elem_tac
      | scalar_tac
      | (refine ⟨?_, ?_⟩ <;> fin_tac)
      | (intro h; simp at h; done)
      | (simp_all; done)
      | (simp_all <;> scalar_tac)
      | (simp; done)
      | (simp [alloc.vec.Vec.new] <;> scalar_tac)
      | decide
