      one_line_loop text out ps i ⦃ r => Good r ⦄ := by
  intro n
  induction n with
  | zero =>
    intro out ps i hn
    exact absurd hn (Nat.not_lt_zero _)
  | succ n ih =>
    intro out ps i hn hP hlen hps
    try have htl := text.property
    first
    | unfold one_line_loop
    | rw [one_line_loop]
    try (first | rw [loop] | unfold loop)
    try simp only []
    try dsimp only
    try rw [one_line_loop.body]
    try simp only [bind_assoc', ite_bind', ok_bind', decide_eq_true_eq]
    step*
    all_goals first
      | done
      | (apply ih <;> fin_tac)
      | (unfold one_line_loop at ih; apply ih <;> fin_tac)
      | (apply spec_of_eq rfl <;> fin_tac)
      | fin_tac

@[step] theorem one_line_loop_spec (text out : alloc.vec.Vec U32) (ps : Bool) (i : Usize)
    (hP : Good out) (hlen : out.val.length ≤ i.val)
    (hps : ps = true → out.val.length + 1 ≤ i.val) :
