      truncate_loop xs limit out i ⦃ r => r.val.length ≤ limit.val ∧ Good r ⦄ := by
  intro n
  induction n with
  | zero =>
    intro out i hn
    exact absurd hn (Nat.not_lt_zero _)
  | succ n ih =>
    intro out i hn hP hlen hi
    try have htl := xs.property
    first
    | unfold truncate_loop
    | rw [truncate_loop]
    try (first | rw [loop] | unfold loop)
    try simp only []
    try dsimp only
    try rw [truncate_loop.body]
    try simp only [bind_assoc', ite_bind', ok_bind', decide_eq_true_eq]
