      | done
      | (apply ih <;> fin_tac)
      | (unfold truncate_loop at ih; apply ih <;> fin_tac)
      | (apply spec_of_eq rfl <;> fin_tac)
      | fin_tac

@[step] theorem truncate_loop_spec (xs : alloc.vec.Vec U32) (limit : Usize)
    (out : alloc.vec.Vec U32) (i : Usize)
    (hxs : Good xs) (hP : Good out) (hlen : out.val.length = i.val) (hi : i.val ≤ limit.val) :
    truncate_loop xs limit out i ⦃ r => r.val.length ≤ limit.val ∧ Good r ⦄ :=
  truncate_loop_aux xs limit hxs _ out i (Nat.lt_succ_self _) hP hlen hi

@[step] theorem truncate_spec (xs : alloc.vec.Vec U32) (limit : Usize) (hxs : Good xs) :
    truncate xs limit ⦃ r => r.val.length ≤ limit.val ∧ Good r ⦄ := by
