/// Words joined by single spaces, then the first `limit` code points.
pub fn one_line(text: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut pending_space = false;
    let mut i = 0;
    while i < text.len() {
        let c = text[i];
        if is_space(c) {
            if out.len() > 0 {
                pending_space = true;
            }
        } else {
            if pending_space {
                if out.len() < limit {
                    out.push(0x20);
                }
                pending_space = false;
            }
            if out.len() < limit {
                out.push(c);
            }
        }
        i += 1;
    }
    truncate(&out, limit)
}

/// The first `limit` code points of `xs`, with any whitespace written as 0x20.
pub fn truncate(xs: &Vec<u32>, limit: usize) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut i = 0;
    while i < xs.len() {
        let c = xs[i];
        if out.len() < limit {
            if is_space(c) {
                out.push(0x20);
            } else {
                out.push(c);
            }
        }
        i += 1;
    }
    out
