import Statements

open Aeneas Aeneas.Std Result
open cores

namespace Trial

set_option maxHeartbeats 2000000

local notation "LB" => ([0x0A, 0x0B, 0x0C, 0x0D, 0x85, 0x2028, 0x2029] : List Nat)

def Good (v : alloc.vec.Vec U32) : Prop := ∀ c ∈ v.val, c.val ∉ LB

theorem good_of_nil {v : alloc.vec.Vec U32} (h : v.val = []) : Good v := by
  intro c hc
  rw [h] at hc
  cases hc

theorem good_push {v w : alloc.vec.Vec U32} {x : U32} (hv : Good v) (hx : x.val ∉ LB)
    (hw : w.val = v.val ++ [x]) : Good w := by
  intro c hc
  rw [hw, List.mem_append, List.mem_singleton] at hc
  rcases hc with hc | hc
  · exact hv c hc
  · subst hc
    exact hx

theorem push_len {v w : alloc.vec.Vec U32} {x : U32}
    (hw : w.val = v.val ++ [x]) : w.val.length = v.val.length + 1 := by
  rw [hw, List.length_append, List.length_singleton]

theorem space_good : (32#u32).val ∉ LB := by
  first
  | decide
  | (simp; done)
  | (intro h; simp at h)

theorem notL_of {n : Nat}
    (h : n < 10 ∨ (13 < n ∧ n < 133) ∨ (133 < n ∧ n < 8232) ∨ 8233 < n) : n ∉ LB := by
  intro hm
  have h2 : n = 10 ∨ n = 11 ∨ n = 12 ∨ n = 13 ∨ n = 133 ∨ n = 8232 ∨ n = 8233 := by
    simpa using hm
  rcases h2 with rfl | rfl | rfl | rfl | rfl | rfl | rfl <;>
    first
    | (simp at h)
    | (revert h; decide)

theorem spec_of_eq {α : Type} {x : Result α} {y : α} {P : α → Prop} (h : x = ok y) (hP : P y) :
    x ⦃ r => P r ⦄ := by
  subst h
  first
  | exact hP
  | (simp only [WP.spec_ok]; exact hP)
  | (simpa using hP)
  | (simp [WP.spec, hP])

theorem ite_step {p : Prop} [Decidable p] {c : U32} {v : Bool} {rest : Result Bool}
    (hv : v = false → p → c.val ∉ LB)
    (hr : ¬ p → rest ⦃ b => b = false → c.val ∉ LB ⦄) :
    (if p then ok v else rest) ⦃ b => b = false → c.val ∉ LB ⦄ := by
  by_cases h : p
  · rw [if_pos h]
    exact spec_of_eq rfl (fun hb => hv hb h)
  · rw [if_neg h]
    exact hr h

macro "nl_tac" : tactic => `(tactic| first
  | scalar_tac
  | (left; scalar_tac)
  | (right; left; constructor <;> scalar_tac)
  | (right; right; left; constructor <;> scalar_tac)
  | (right; right; right; scalar_tac))

@[step] theorem is_space_spec (c : U32) : is_space c ⦃ b => b = false → c.val ∉ LB ⦄ := by
  unfold is_space
  repeat
    refine ite_step ?_ ?_
    · first
        | (intro hb; exact absurd hb (by decide))
        | (intro _ _; apply notL_of; nl_tac)
    intro _
  refine spec_of_eq rfl ?_
  intro _
  apply notL_of
  nl_tac

macro "elem_tac" : tactic => `(tactic| first
  | assumption
  | exact space_good
  | (apply ‹_ = false → _›
     first
       | assumption
       | rfl
       | (simp_all; done)
       | (simp at *; assumption)))

macro "tclose" : tactic => `(tactic| first
  | assumption
  | trivial
  | (apply good_of_nil; first | rfl | (simp; done))
  | (refine good_push ‹Good _› ?_ ‹_›; elem_tac)
  | (have := push_len ‹_›; scalar_tac)
  | exact Nat.zero_le _
  | scalar_tac
  | exact ⟨‹_›, ‹Good _›⟩
  | refine spec_of_eq rfl ⟨‹_›, ‹Good _›⟩
  | (simp; done)
  | (simp_all; done)
  | (simp_all; scalar_tac))

theorem one_line_loop_aux (text : alloc.vec.Vec U32) (limit : Usize) :
    ∀ (n : Nat) (out : alloc.vec.Vec U32) (ps : Bool) (i : Usize),
      text.val.length - i.val < n →
      one_line_loop text limit out ps i ⦃ _ => True ⦄ := by
  intro n
  induction n with
  | zero =>
    intro out ps i hn
    exact absurd hn (Nat.not_lt_zero _)
  | succ n ih =>
    intro out ps i hn
    have htl := text.property
    unfold one_line_loop
    step*
    all_goals first
      | trivial
      | (apply ih; first | scalar_tac | (simp_all; scalar_tac))
      | scalar_tac
      | (simp_all; done)
      | (simp_all; scalar_tac)

@[step] theorem one_line_loop_spec (text : alloc.vec.Vec U32) (limit : Usize)
    (out : alloc.vec.Vec U32) (ps : Bool) (i : Usize) :
    one_line_loop text limit out ps i ⦃ _ => True ⦄ :=
  one_line_loop_aux text limit _ out ps i (Nat.lt_succ_self _)

theorem truncate_loop_aux (xs : alloc.vec.Vec U32) (limit : Usize) :
    ∀ (n : Nat) (out : alloc.vec.Vec U32) (i : Usize),
      xs.val.length - i.val < n → Good out → out.val.length ≤ limit.val →
      truncate_loop xs limit out i ⦃ r =>
        r.val.length ≤ limit.val ∧ (∀ c ∈ r.val, c.val ∉ LB) ⦄ := by
  intro n
  induction n with
  | zero =>
    intro out i hn
    exact absurd hn (Nat.not_lt_zero _)
  | succ n ih =>
    intro out i hn hP hlim
    have htl := xs.property
    unfold truncate_loop
    step*
    all_goals first
      | (apply ih <;> tclose)
      | tclose

@[step] theorem truncate_loop_spec (xs : alloc.vec.Vec U32) (limit : Usize)
    (out : alloc.vec.Vec U32) (i : Usize)
    (hP : Good out) (hlim : out.val.length ≤ limit.val) :
    truncate_loop xs limit out i ⦃ r =>
      r.val.length ≤ limit.val ∧ (∀ c ∈ r.val, c.val ∉ LB) ⦄ :=
  truncate_loop_aux xs limit _ out i (Nat.lt_succ_self _) hP hlim

@[step] theorem truncate_spec (xs : alloc.vec.Vec U32) (limit : Usize) :
    truncate xs limit ⦃ r =>
      r.val.length ≤ limit.val ∧ (∀ c ∈ r.val, c.val ∉ LB) ⦄ := by
  unfold truncate
  step*
  all_goals tclose

theorem holds : Statements.one_line_spec := by
  unfold Statements.one_line_spec
  intro reply limit
  unfold one_line
  step*
  all_goals tclose

end Trial
